using System.Text.RegularExpressions;

namespace MyApp.Evaluation;

/// <summary>
/// Lightweight loader for evaluation.yml scenarios.
/// </summary>
public static partial class ScenarioLoader
{
    public static List<EvaluationScenario> Load(string path)
    {
        var results = new List<EvaluationScenario>();
        var lines = File.ReadAllLines(path);

        EvaluationScenario? current = null;
        foreach (var line in lines)
        {
            var nameMatch = NamePattern().Match(line);
            if (nameMatch.Success)
            {
                current = new EvaluationScenario { Name = nameMatch.Groups[1].Value };
                results.Add(current);
                continue;
            }

            if (current is null) continue;

            var promptMatch = PromptPattern().Match(line);
            if (promptMatch.Success)
            {
                current.Prompt = promptMatch.Groups[1].Value;
                continue;
            }

            var containsMatch = ContainsPattern().Match(line);
            if (containsMatch.Success)
            {
                current.ExpectedContains = containsMatch.Groups[1].Value;
            }
        }

        return results;
    }

    [GeneratedRegex(@"^\s*-\s*name:\s*(.+)$")]
    private static partial Regex NamePattern();

    [GeneratedRegex(@"^\s*prompt:\s*""(.+)""$")]
    private static partial Regex PromptPattern();

    [GeneratedRegex(@"^\s*contains:\s*""(.+)""$")]
    private static partial Regex ContainsPattern();
}

public class EvaluationScenario
{
    public string Name { get; set; } = string.Empty;
    public string Prompt { get; set; } = string.Empty;
    public string? ExpectedContains { get; set; }
}

